using LealControl.BuildingBlocks.Tenancy;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace LealControl.Modules.Finance.Infrastructure;

public enum FinancialAccountType { Bank, Cash, Wallet, Investment }
public enum FinancialMovementKind { Credit, Debit }
public enum FinancialReconciliationStatus { Available, Suggested, Reconciled, Excluded }
public enum ReceivedChequeStatus { Available, Deposited, Presented, Credited, UsedForPayment, Rejected, Expired, Cancelled }
public enum ChequeDirection { Received, Issued }
public sealed class ReceivedCheque { public Guid Id { get; set; } public Guid TenantId { get; set; } public string CheckNumber { get; set; } = ""; public string? EcheqId { get; set; } public string? Cmc7 { get; set; } public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime? IssueDateUtc { get; set; } public DateTime? DueDateUtc { get; set; } public string? IssuerName { get; set; } public string? IssuerTaxId { get; set; } public string? BankName { get; set; } public string? ReceivedFrom { get; set; } public ChequeDirection Direction { get; set; } = ChequeDirection.Received; public ReceivedChequeStatus Status { get; set; } = ReceivedChequeStatus.Available; public Guid? BankAccountId { get; set; } public Guid? BankMovementId { get; set; } public DateTime? DepositedAtUtc { get; set; } public DateTime? CreditedAtUtc { get; set; } public string? Notes { get; set; } public Guid? CollectionReceiptId { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class FinancialAccount { public Guid Id { get; set; } public Guid TenantId { get; set; } public string Name { get; set; } = ""; public string Currency { get; set; } = "ARS"; public FinancialAccountType Type { get; set; } public decimal OpeningBalance { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAtUtc { get; set; } }
public sealed class FinancialMovement { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public FinancialMovementKind Kind { get; set; } public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime OperationDateUtc { get; set; } public string Description { get; set; } = ""; public string? ExternalReference { get; set; } public Guid? TransferId { get; set; } public decimal? ReportedBalance { get; set; } public FinancialReconciliationStatus ReconciliationStatus { get; set; } = FinancialReconciliationStatus.Available; public string? LinkedEntityType { get; set; } public Guid? LinkedEntityId { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class CollectionReceipt { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public Guid? CustomerId { get; set; } public Guid? InvoiceId { get; set; } public string ReceiptNumber { get; set; } = ""; public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public string? InvoiceCurrency { get; set; } public decimal? InvoiceAmount { get; set; } public decimal? InvoiceExchangeRate { get; set; } public decimal? PaymentExchangeRate { get; set; } public decimal? SuggestedAdjustmentArs { get; set; } public string? SuggestedAdjustmentType { get; set; } public DateTime ReceiptDateUtc { get; set; } public string Description { get; set; } = ""; public string Status { get; set; } = "Confirmed"; public DateTime CreatedAtUtc { get; set; } }
public sealed record CreateAccountRequest(string Name, string Currency, FinancialAccountType Type, decimal OpeningBalance);
public sealed class CollectionReceiptLine { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid ReceiptId { get; set; } public string Method { get; set; } = ""; public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public Guid? AccountId { get; set; } public Guid? BankMovementId { get; set; } public Guid? ChequeId { get; set; } public string? RetentionType { get; set; } public string? RetentionCertificate { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed record CreateMovementRequest(Guid AccountId, FinancialMovementKind Kind, decimal Amount, string Currency, DateTime OperationDateUtc, string Description, string? ExternalReference);
public sealed record TransferRequest(Guid FromAccountId, Guid ToAccountId, decimal Amount, string Currency, DateTime OperationDateUtc, string Description);

public sealed class FinanceDbContext(DbContextOptions<FinanceDbContext> options) : DbContext(options)
{
    public const string Schema = "finance";
    public DbSet<FinancialAccount> Accounts => Set<FinancialAccount>();
    public DbSet<FinancialMovement> Movements => Set<FinancialMovement>();
    public DbSet<CollectionReceipt> CollectionReceipts => Set<CollectionReceipt>();
    public DbSet<ReceivedCheque> ReceivedCheques => Set<ReceivedCheque>();
    protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.HasDefaultSchema(Schema); modelBuilder.Entity<FinancialAccount>(b => { b.ToTable("FinancialAccounts"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(180).IsRequired(); b.Property(x => x.Currency).HasMaxLength(8).IsRequired(); b.Property(x => x.OpeningBalance).HasPrecision(18, 2); b.HasIndex(x => new { x.TenantId, x.Name }); }); modelBuilder.Entity<FinancialMovement>(b => { b.ToTable("FinancialMovements"); b.HasKey(x => x.Id); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(8); b.Property(x => x.Description).HasMaxLength(500); b.Property(x => x.ExternalReference).HasMaxLength(180); b.HasIndex(x => new { x.TenantId, x.AccountId, x.OperationDateUtc }); }); modelBuilder.Entity<CollectionReceipt>(b => { b.ToTable("CollectionReceipts"); b.HasKey(x => x.Id); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(8).IsRequired(); b.Property(x => x.ReceiptNumber).HasMaxLength(40).IsRequired(); b.Property(x => x.Description).HasMaxLength(500).IsRequired(); b.Property(x => x.Status).HasMaxLength(30).IsRequired(); }); }
    public DbSet<CollectionReceiptLine> CollectionReceiptLines => Set<CollectionReceiptLine>();
}

public static class DependencyInjection
{
    public static IServiceCollection AddFinanceModule(this IServiceCollection services, IConfiguration configuration)
    { var connection = configuration.GetConnectionString("Database") ?? throw new InvalidOperationException("Falta ConnectionStrings:Database."); services.AddDbContext<FinanceDbContext>(o => o.UseNpgsql(connection, n => n.MigrationsHistoryTable("__ef_migrations_history", FinanceDbContext.Schema))); return services; }
    public static IEndpointRouteBuilder MapFinanceModule(this IEndpointRouteBuilder endpoints)
    { var group = endpoints.MapGroup("/api/v1/finance").WithTags("Finance"); group.MapGet("/accounts", async (FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var accounts = await db.Accounts.AsNoTracking().Where(x => x.TenantId == id).OrderBy(x => x.Name).ToListAsync(ct); var balances = await db.Movements.AsNoTracking().Where(x => x.TenantId == id).GroupBy(x => x.AccountId).Select(g => new { AccountId = g.Key, Credit = g.Where(x => x.Kind == FinancialMovementKind.Credit).Sum(x => (decimal?)x.Amount) ?? 0, Debit = g.Where(x => x.Kind == FinancialMovementKind.Debit).Sum(x => (decimal?)x.Amount) ?? 0 }).ToDictionaryAsync(x => x.AccountId, ct); return Results.Ok(accounts.Select(a => new { a.Id, a.Name, a.Currency, a.Type, IsActive = a.IsActive, Balance = a.OpeningBalance + (balances.TryGetValue(a.Id, out var b) ? b.Credit - b.Debit : 0) })); }); group.MapPost("/accounts", async (CreateAccountRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var account = new FinancialAccount { Id = Guid.NewGuid(), TenantId = id, Name = body.Name.Trim(), Currency = body.Currency.Trim().ToUpperInvariant(), Type = body.Type, OpeningBalance = body.OpeningBalance, CreatedAtUtc = DateTime.UtcNow }; db.Accounts.Add(account); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/finance/accounts/{account.Id}", account); }); group.MapPost("/movements", async (CreateMovementRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; if (!await db.Accounts.AnyAsync(x => x.Id == body.AccountId && x.TenantId == id && x.IsActive, ct)) return Results.NotFound("Cuenta financiera inexistente."); var movement = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = body.AccountId, Kind = body.Kind, Amount = body.Amount, Currency = body.Currency.Trim().ToUpperInvariant(), OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = body.ExternalReference, CreatedAtUtc = DateTime.UtcNow }; db.Movements.Add(movement); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/finance/movements/{movement.Id}", movement); }); group.MapPost("/transfers", async (TransferRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; if (body.FromAccountId == body.ToAccountId || body.Amount <= 0) return Results.BadRequest("Indicá cuentas distintas y un importe mayor a cero."); var accounts = await db.Accounts.Where(x => x.TenantId == id && x.IsActive && (x.Id == body.FromAccountId || x.Id == body.ToAccountId)).ToListAsync(ct); var from = accounts.SingleOrDefault(x => x.Id == body.FromAccountId); var to = accounts.SingleOrDefault(x => x.Id == body.ToAccountId); if (from is null || to is null) return Results.NotFound("Una de las cuentas no existe o está inactiva."); var currency = body.Currency.Trim().ToUpperInvariant(); if (from.Currency != currency || to.Currency != currency) return Results.BadRequest("La moneda debe coincidir con ambas cuentas."); var balances = await db.Movements.Where(x => x.TenantId == id && x.AccountId == from.Id).GroupBy(x => x.AccountId).Select(g => g.Sum(x => x.Kind == FinancialMovementKind.Credit ? x.Amount : -x.Amount)).SingleOrDefaultAsync(ct); if (from.OpeningBalance + balances < body.Amount) return Results.BadRequest("La cuenta de origen no tiene saldo suficiente."); var transferId = Guid.NewGuid(); db.Movements.AddRange(new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = from.Id, Kind = FinancialMovementKind.Debit, Amount = body.Amount, Currency = currency, OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = $"TRANSFER:{transferId}", TransferId = transferId, CreatedAtUtc = DateTime.UtcNow }, new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = to.Id, Kind = FinancialMovementKind.Credit, Amount = body.Amount, Currency = currency, OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = $"TRANSFER:{transferId}", TransferId = transferId, CreatedAtUtc = DateTime.UtcNow }); await db.SaveChangesAsync(ct); return Results.Ok(new { transferId, amount = body.Amount, currency }); }); FinanceImport.MapFinanceImportEndpoints(endpoints); return endpoints; }
}



